import urllib.request
import urllib.error
import time


class Exception(Exception):
    """Base exception for API errors."""
    pass


class ClientError(Exception):
    """Raised for HTTP 4xx errors (except 429)."""
    pass


class RateLimitError(Exception):
    """Raised when rate limit (429) is exceeded after retries."""
    pass


class ServerError(Exception):
    """Raised for HTTP 5xx errors after retries."""
    pass


class ConnectionError(Exception):
    """Raised for network errors after retries."""
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"
        last_exception = None

        # Handle 429 with exponential backoff
        for attempt in range(3):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.getcode()
                    if status == 429:
                        if attempt < 2:
                            wait = 0.5 * (2 ** attempt)
                            time.sleep(wait)
                            continue
                        else:
                            raise RateLimitError(f"Rate limit exceeded after 3 attempts")
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    if attempt < 2:
                        wait = 0.5 * (2 ** attempt)
                        time.sleep(wait)
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after 3 attempts")
                elif 500 <= status < 600:
                    if attempt == 0:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error {status}")
                else:
                    raise ClientError(f"Client error {status}")

        # Handle 5xx with single retry
        for attempt in range(1):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.getcode()
                    if 500 <= status < 600:
                        raise ServerError(f"Server error {status}")
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                status = e.code
                if 500 <= status < 600:
                    raise ServerError(f"Server error {status}")
                return e.read().decode('utf-8')

        # Handle network errors with single retry
        for attempt in range(1):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.URLError as e:
                if attempt == 0:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError(f"Connection error: {e.reason}")

        # If we reach here, something unexpected happened
        raise Exception("Unexpected error occurred")
